SELECT  FROM ai_timer
WHERE deleted = 0

    AND owner_user_id = #{ownerId}


    AND owner_user_id = #{ownerFilter}


    AND status = #{status}

ORDER BY
    CASE WHEN status IN ('AWAITING_CONFIRM', 'FIRING', 'PENDING') THEN 0 ELSE 1 END,
    CASE WHEN status IN ('AWAITING_CONFIRM', 'FIRING', 'PENDING') THEN fire_at END ASC,
    fire_at DESC
LIMIT #{limit}

SELECT COUNT(*) FROM ai_timer
WHERE deleted = 0 AND status IN ('PENDING', 'FIRING', 'AWAITING_CONFIRM')

    AND owner_user_id = #{ownerId}

SELECT  FROM ai_timer
WHERE deleted = 0 AND status = 'PENDING' AND fire_at <= #{now}
ORDER BY fire_at ASC
LIMIT #{limit}

mapper.update:
UPDATE ai_timer
SET status = 'FAILED', fired_at = #{firedAt}, ok = 0, error_message = #{errorMessage}
WHERE id = #{id} AND status = 'FIRING'

UPDATE ai_timer
SET status = 'FIRING', confirmed_by = #{confirmedBy}, claimed_at = #{claimedAt}
WHERE id = #{id} AND status = 'AWAITING_CONFIRM' AND deleted = 0

UPDATE ai_timer SET status = 'CANCELLED', cancelled_at = #{cancelledAt}
WHERE status IN ('PENDING', 'AWAITING_CONFIRM') AND deleted = 0

    AND owner_user_id = #{ownerId}


